import{_ as e,o as t,c as i,a}from"./app.1844d130.js";var r="/aktivitaeten/BDM-2026-10/00_10-2026.jpg",n="/aktivitaeten/BDM-2026-10/01_10-2026.jpg",s="/aktivitaeten/BDM-2026-10/02_10-2026.jpg",d="/aktivitaeten/BDM-2026-10/03_10-2026.jpg",o="/aktivitaeten/BDM-2026-10/04_10-2026.jpg",m="/aktivitaeten/BDM-2026-10/05_10-2026.jpg",l="/aktivitaeten/BDM-2026-10/06_10-2026.jpg",p="/aktivitaeten/BDM-2026-10/07_10-2026.jpg",_="/aktivitaeten/BDM-2026-10/08_10-2026.jpg",g="/aktivitaeten/BDM-2026-10/09_10-2026.jpg",c="/aktivitaeten/BDM-2026-10/10_10-2026.jpg",u="/aktivitaeten/BDM-2026-10/11_10-2026.jpg",h="/aktivitaeten/BDM-2026-10/12_10-2026.jpg",B="/aktivitaeten/BDM-2026-10/13_10-2026.jpg",v="/aktivitaeten/BDM-2026-10/14_10-2026.jpg",k="/aktivitaeten/BDM-2026-10/15_10-2026.jpg",M="/aktivitaeten/BDM-2026-10/16_10-2026.jpg",D="/aktivitaeten/BDM-2026-10/17_10-2026.jpg",b="/aktivitaeten/BDM-2026-10/18_10-2026.jpg",f="/aktivitaeten/BDM-2026-10/19_10-2026.jpg",j="/aktivitaeten/BDM-2026-10/20_10-2026.jpg",A="/aktivitaeten/BDM-2026-10/21_10-2026.jpg",w="/aktivitaeten/BDM-2026-10/22_10-2026.jpg",O="/aktivitaeten/BDM-2026-10/23_10-2026.jpg",F="/aktivitaeten/BDM-2026-10/24_10-2026.jpg",S="/aktivitaeten/BDM-2026-10/25_10-2026.jpg",W="/aktivitaeten/BDM-2026-10/26_10-2026.jpg";const z={},L=a('<h1 id="bilder-des-monats-oktober-2026" tabindex="-1"><a class="header-anchor" href="#bilder-des-monats-oktober-2026" aria-hidden="true">#</a> Bilder des Monats Oktober 2026</h1><hr><p>SOTA Aktivierung von DL/AL-107 Piesenkopf 1630m von DF6TG. Bei Kaiserwetter ging es wieder mal auf den Berg. Nicht allzu hoch,aber dennoch ein wunderbarer Ausblick und Funkberg. Mit im Rucksack war der Xiegu 6100 und die PAC12 vertikal Antenne. 20m gingen wie geschnitten Brot. Zahlreiche sch\xF6ne Verbindungen quer durch Europa. Das Highlight war dann noch zum Schlu\xDF ein QSO auf 17m nach Japan,in die N\xE4he von Tokio\u{1F4AF} Aktivierung somit erfolgreich.</p><p><img src="'+r+'" alt="Bilder des Monats"><img src="'+n+'" alt="Bilder des Monats"><img src="'+s+'" alt="Bilder des Monats"><img src="'+d+'" alt="Bilder des Monats"><img src="'+o+'" alt="Bilder des Monats"><img src="'+m+'" alt="Bilder des Monats"><img src="'+l+'" alt="Bilder des Monats"><img src="'+p+'" alt="Bilder des Monats"></p><hr><p>Heute ging es f\xFCr DF6TG und YL zusammen auf Tour. Funken in einer traumhaften Bergkulisse\u{1F64F}</p><p><img src="'+_+'" alt="Bilder des Monats"></p><hr><p>Ich wollte heute endlich mal von meinen Haus-Trails ein paar QSOs auf 80m machen damit ich wenigstens da 10 B\xE4nder habe. Antenne war nicht optimal, 20m Draht mit Tuner angepasst und nur 5 W aber es ging. 6 QSOs in CW auf 80m, dann war leider der Akku leer. Hatte ich vergessen zu laden nach der letzten Aktivierung. 73 de DF9HC</p><p><img src="'+g+'" alt="Bilder des Monats"></p><hr><p>Obwohl ich heute keine Aktivierungspunkte vergeben konnte hab ich trotzdem einen sch\xF6nen Drau\xDFenfunk-Spot gefunden und mit 5 W etwas im WAG Contest, bei POTA und JOTA mitgespielt. 73 de LZ/DF9HC</p><p><img src="'+c+'" alt="Bilder des Monats"><img src="'+u+'" alt="Bilder des Monats"><img src="'+h+'" alt="Bilder des Monats"><img src="'+B+'" alt="Bilder des Monats"><img src="'+v+'" alt="Bilder des Monats"></p><hr><p>DB6NL: Ich hab heute auf Baltrum mit 5W im WAG mitgemischt. Mit der geringen Leistung und der verk\xFCrzten Groundplane (HF-P1) hat auf 40m nicht viel funktioniert. Die meisten QSOs kamen auf 20m ins Log. Leider waren bei 10 Grad und 4-6 bft die Finger nach 1:40h abgefroren und ich bin zur\xFCck in die Fewo. Die Bank steht leider au\xDFerhalb der Parkgrenzen von DE-0094\u2026</p><p><img src="'+k+'" alt="Bilder des Monats"><img src="'+M+'" alt="Bilder des Monats"></p><hr><p>Ich hab heute seit l\xE4ngerem mal wieder einen Park in Bulgarien aktiviert, den Rila Nationalpark (BG-0085). Mit 5 W 28 QSOs auf 3 B\xE4ndern, CW und SSB. Ein paar Zuschauer hatte ich auch. 73 de LZ/DF9HC</p><p><img src="'+D+'" alt="Bilder des Monats"><img src="'+b+'" alt="Bilder des Monats"><img src="'+f+'" alt="Bilder des Monats"><img src="'+j+'" alt="Bilder des Monats"><img src="'+A+'" alt="Bilder des Monats"><img src="'+w+'" alt="Bilder des Monats"></p><hr><p>DB7GKA am sp\xE4ten Nachmittag des 31.10.2026 beim Weiher am Hirschbrunnen im POTA-Park DE-1152 Perlacher Forst, zum ausprobieren der 12,5 Meter langen EFRW mit 1:9 UnUn an einem 12 Meter langen GFK-Mast. Es kamen mittels CW auf den B\xE4ndern 20, 30, 40 und 80 Meter insgesamt 34 QSOs ins Log.</p><p><img src="'+O+'" alt="Bilder des Monats"><img src="'+F+'" alt="Bilder des Monats"><img src="'+S+'" alt="Bilder des Monats"><img src="'+W+'" alt="Bilder des Monats"></p>',22),T=[L];function G(H,P){return t(),i("div",null,T)}var E=e(z,[["render",G],["__file","2026-10-30-Bilder-Des-Monats-Oktober.html.vue"]]);export{E as default};
